{"path":"/workspace/scripts/reconcile-terms-of-reference.mjs","text":"#!/usr/bin/env bun
// Diffs a fresh symbol extraction against the EXISTING canonical registry
// in TERMS_OF_REFERENCE.md. Neither extract-symbols.mjs (describes what's
// currently in the docs, no memory of any prior state) nor
// adjudicate-symbol-conflicts.mjs (judges ambiguity within one extraction
// pass) does this job -- this one's job is "does the current state still
// agree with what we already declared canonical," which needs the prior
// declaration as an input, not just a fresh read of the docs. Separate
// script on purpose, same reasoning as keeping extraction and adjudication
// apart: a different question shape gets its own tool, not a mode flag on
// an existing one.
//
// Four outcomes per symbol, not two -- "changed" isn't one bucket:
//   UNCHANGED     -- kind matches the registry. Nothing to do.
//   VIOLATION     -- the registry has this symbol; the fresh extraction's
//                     kind disagrees. Per the ToR's own stated rule, the
//                     document is wrong, not the registry -- this is the
//                     halt.
//   NEW           -- fresh extraction found a symbol the registry doesn't
//                     have yet. Not wrong, just undecided -- needs a human
//                     call on whether it's added.
//   MISSING       -- the registry has a symbol the fresh extraction found
//                     nowhere. Possibly renamed, possibly dropped
//                     intentionally -- needs a human call, not an assumption.
//
// Usage:
//   bun scripts/reconcile-terms-of-reference.mjs [symbols/<ts>.json] [TERMS_OF_REFERENCE.md]
//   (both default to the newest symbols/*.json and ./TERMS_OF_REFERENCE.md)

import { readdir, readFile } from "node:fs/promises";
import { join } from "node:path";

function log(msg) {
  process.stderr.write(`[reconcile-tor] ${msg}\n`);
}

let symbolsPath = process.argv[2];
if (!symbolsPath) {
  const files = (await readdir("symbols")).filter((f) => f.endsWith(".json") && !f.startsWith("adjudicated-")).sort();
  if (files.length === 0) {
    console.error("no symbols/*.json found -- run extract-symbols.mjs first");
    process.exit(1);
  }
  symbolsPath = join("symbols", files.at(-1));
  log(`no extraction path given, using newest: ${symbolsPath}`);
}
const torPath = process.argv[3] ?? "TERMS_OF_REFERENCE.md";

const { symbols: fresh } = JSON.parse(await readFile(symbolsPath, "utf8"));
const torText = await readFile(torPath, "utf8");

// Parse the "Symbol registry" markdown table: rows of
// | `name` | declared in | kind | unit | status |
// Backtick-wrapped name, everything else plain cell text. Deliberately a
// narrow parser for exactly this table's shape, not a general markdown
// table reader -- if the table's shape changes this should fail loudly,
// not silently misparse.
const registry = new Map(); // name -> { declaredIn, kind }
for (const line of torText.split("\n")) {
  const m = line.match(/^\|\s*`([^`]+)`\s*\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|\s*([^|]+?)\s*\|\s*$/);
  if (!m) continue;
  const [, name, declaredIn, kind] = m;
  registry.set(name, { declaredIn: declaredIn.replace(/\*\*/g, ""), kind });
}
log(`parsed ${registry.size} symbol(s) from ${torPath}`);
log(`fresh extraction has ${fresh.length} symbol(s) from ${symbolsPath}`);

const freshByName = new Map(fresh.map((s) => [s.name, s]));

const unchanged = [];
const violations = [];
const news = [];
const missing = [];

for (const [name, entry] of registry) {
  const f = freshByName.get(name);
  if (!f) {
    missing.push({ name, ...entry });
    continue;
  }
  if (f.kind === entry.kind) {
    unchanged.push(name);
  } else {
    violations.push({ name, registryKind: entry.kind, freshKind: f.kind, declaredIn: f.declared_in, references: f.references });
  }
}
for (const [name, f] of freshByName) {
  if (!registry.has(name)) news.push({ name, kind: f.kind, declaredIn: f.declared_in });
}

log("");
log(`${unchanged.length} unchanged, ${violations.length} violation(s), ${news.length} new, ${missing.length} missing`);

if (violations.length > 0) {
  log("");
  log(`HALT -- ${violations.length} symbol(s) now disagree with the registry:`);
  for (const v of violations) {
    log("");
    log(`  ${v.name}: registry says "${v.registryKind}", current docs say "${v.freshKind}"`);
    log(`    declared in: ${v.declaredIn}`);
    for (const r of v.references.slice(0, 3)) log(`    - ${r.document}: ${r.quote}`);
  }
}

if (news.length > 0) {
  log("");
  log(`${news.length} new symbol(s), not yet in the registry -- add deliberately, don't let usage alone make them canonical:`);
  for (const n of news) log(`  ${n.name} (${n.declaredIn}): "${n.kind}"`);
}

if (missing.length > 0) {
  log("");
  log(`${missing.length} registry symbol(s) no longer found anywhere -- renamed or genuinely dropped? verify, don't assume:`);
  for (const m of missing) log(`  ${m.name} (was: ${m.declaredIn}, "${m.kind}")`);
}

process.exit(violations.length > 0 ? 1 : 0);
"}

